import { test, expect, type Page } from '@playwright/test';
import { AxeBuilder } from '@axe-core/playwright';

const targetUrl = 'https://practice.expandtesting.com/register';

const locators = (page: Page) => ({
  usernameInput: page.getByRole('textbox', { name: 'Username' }),
  passwordInput: page.getByRole('textbox', { name: 'Password' }),
  confirmPasswordInput: page.getByRole('textbox', { name: 'Confirm Password' }),
  registerButton: page.getByRole('button', { name: 'Register' }),
});

test.describe('Registration', () => {

  test.beforeEach(async ({ page }) => {
    await page.goto(targetUrl);
  });

  test.afterEach(async ({ page }, testInfo) => {
    if (testInfo.status!== testInfo.expectedStatus) {
      await testInfo.attachments.attach('screenshot', {
        body: await page.screenshot(),
        contentType: 'image/png',
      });
    }
  });

  test('registers a new account with valid credentials', async ({ page }) => {
    const el = locators(page);
    await test.step('fills the username input', async () => {
      await el.usernameInput.fill('testuser2026');
    });
    await test.step('fills the password input', async () => {
      await el.passwordInput.fill('Passw0rd!23');
    });
    await test.step('confirms the password', async () => {
      await el.confirmPasswordInput.fill('Passw0rd!23');
    });
    await test.step('clicks the register button', async () => {
      await el.registerButton.click();
    });
    await test.step('verifies the registration form accepts the input', async () => {
      await expect(el.usernameInput).toBeVisible();
    });
  });

  test('accessibility: no WCAG 2.1 A/AA violations', async ({ page }) => {
    const results = await new AxeBuilder({ page })
     .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'])
      .analyze();
    expect(results.violations).toEqual([]);
  });

});
